c11.referenceSolution:
static int compareService(const void *left, const void *right) {
  long long a = *(const long long *)left;
  long long b = *(const long long *)right;
  return (a > b) - (a < b);
}

long long solve(const long long *values, int n) {
  if (n <= 0) return 0;
  long long *times = (long long *)malloc(sizeof(long long) * (size_t)n);
  memcpy(times, values, sizeof(long long) * (size_t)n);
  qsort(times, (size_t)n, sizeof(long long), compareService);
  long long elapsed = 0, total = 0;
  for (int i = 0; i < n; i++) {
    elapsed += times[i];
    total += elapsed;
  }
  free(times);
  return total;
}

