long long solve(const vector<long long>& values) {
  vector<long long> times(values);
  sort(times.begin(), times.end());
  long long elapsed = 0, total = 0;
  for (long long service : times) {
    elapsed += service;
    total += elapsed;
  }
  return total;
}

